//! The cluster CA (`<data_dir>/tls/ca.{crt,key}`, keys 0600, bound to `cluster_id`,
//! D-W5), the node certificate (`ostro://<cluster_id>/node/<node_id>`, D-W20) and CSR
//! signing for worker client certificates (D-W4).
//!
//! Every key is ECDSA P-256 generated by rcgen on aws-lc-rs (never ring). Key files are
//! written 0600 through create-new tmp + fsync + rename + dir fsync; key bytes never reach
//! a log line, a `Debug` impl or an error message.
//!
//! X.509 validity timestamps are the only time this module reads; they are checked by
//! peers, so they come from the system clock (`// clock-exempt`), not the injected clock.

use std::collections::BTreeSet;
use std::fmt;
use std::fs;
use std::io::{self, Write};
use std::net::IpAddr;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

use base64::Engine as _;
use rcgen::{
    BasicConstraints, CertificateParams, CertificateSigningRequestParams, DistinguishedName,
    DnType, ExtendedKeyUsagePurpose, IsCa, Issuer, KeyPair, KeyUsagePurpose,
    PKCS_ECDSA_P256_SHA256, SanType, SerialNumber,
};
use rustls_pki_types::pem::PemObject;
use rustls_pki_types::{CertificateDer, CertificateSigningRequestDer, PrivateKeyDer};
use sha2::{Digest, Sha256};
use x509_parser::extensions::GeneralName;
use x509_parser::oid_registry::{OID_EC_P256, OID_KEY_TYPE_EC_PUBLIC_KEY, OID_SIG_ED25519};
use x509_parser::prelude::{FromDer, X509Certificate, X509CertificationRequest};

use super::TlsError;

/// CA lifetime: 10 years.
pub const CA_LIFETIME: Duration = Duration::from_secs(3653 * 86_400);
/// Node and dev certificate lifetime: 1 year.
pub const LEAF_LIFETIME: Duration = Duration::from_secs(365 * 86_400);
/// A persisted node/dev certificate is re-issued when it expires within this window.
pub const REISSUE_WITHIN: Duration = Duration::from_secs(30 * 86_400);
/// Backdating of `not_before` (clock skew between the CA and its peers).
const BACKDATE_SECS: i64 = 60;
/// Longest token id / worker id accepted in a worker certificate.
pub const MAX_ID_LEN: usize = 64;
/// URI scheme of the node and worker identity SANs.
pub const IDENTITY_SCHEME: &str = "ostro://";

/// Seconds since the Unix epoch.
fn unix_now() -> i64 {
    // clock-exempt: X.509 validity timestamps checked by peers.
    #[allow(clippy::disallowed_methods)]
    let now = std::time::SystemTime::now();
    now.duration_since(std::time::UNIX_EPOCH)
        .map(|d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX))
        .unwrap_or(0)
}

fn cert_err(msg: impl Into<String>) -> TlsError {
    TlsError::Cert(msg.into())
}

fn x509_time(secs: i64) -> Result<x509_parser::time::ASN1Time, TlsError> {
    x509_parser::time::ASN1Time::from_timestamp(secs)
        .map_err(|_| cert_err(format!("certificate time {secs} out of range")))
}

/// Set `not_before = now - 60 s`, `not_after = now + lifetime`.
fn set_validity(p: &mut CertificateParams, lifetime: Duration) -> Result<(), TlsError> {
    let now = unix_now();
    let life = i64::try_from(lifetime.as_secs()).unwrap_or(i64::MAX / 4);
    p.not_before = x509_time(now - BACKDATE_SECS)?.to_datetime();
    p.not_after = x509_time(now.saturating_add(life))?.to_datetime();
    Ok(())
}

/// A random positive 16-byte serial number.
fn random_serial() -> Result<SerialNumber, TlsError> {
    let mut b = [0u8; 16];
    getrandom::fill(&mut b).map_err(|e| cert_err(format!("OS RNG: {e}")))?;
    b[0] &= 0x7f;
    b[0] |= 0x01;
    Ok(SerialNumber::from_slice(&b))
}

/// Lowercase hex.
pub fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        let _ = write!(s, "{b:02x}");
    }
    s
}

/// `sha256:<hex>` of `der`.
pub fn sha256_fingerprint(der: &[u8]) -> String {
    format!("sha256:{}", hex(&Sha256::digest(der)))
}

/// PEM-encode `der` under `label`.
pub fn pem_encode(label: &str, der: &[u8]) -> String {
    let b64 = base64::engine::general_purpose::STANDARD.encode(der);
    let mut out = format!("-----BEGIN {label}-----\n");
    for chunk in b64.as_bytes().chunks(64) {
        out.push_str(std::str::from_utf8(chunk).unwrap_or_default());
        out.push('\n');
    }
    out.push_str(&format!("-----END {label}-----\n"));
    out
}

/// `[A-Za-z0-9._-]{1,max}`.
pub fn valid_id(s: &str, max: usize) -> bool {
    !s.is_empty()
        && s.len() <= max
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'_' | b'-'))
}

// ------------------------------------------------------------------------------------
// File helpers
// ------------------------------------------------------------------------------------

fn io_err(path: &Path, source: io::Error) -> TlsError {
    TlsError::Io {
        path: path.to_path_buf(),
        source,
    }
}

/// Write `bytes` to `path` atomically: create-new tmp (mode `mode`) + fsync + rename +
/// dir fsync.
pub(crate) fn write_atomic(path: &Path, bytes: &[u8], mode: u32) -> Result<(), TlsError> {
    let file_name = path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let tmp = path.with_file_name(format!(".{file_name}.tmp-{}", std::process::id()));
    match fs::remove_file(&tmp) {
        Ok(()) => {}
        Err(e) if e.kind() == io::ErrorKind::NotFound => {}
        Err(e) => return Err(io_err(&tmp, e)),
    }
    let mut opts = fs::OpenOptions::new();
    opts.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.mode(mode);
    }
    #[cfg(not(unix))]
    let _ = mode;
    let mut f = opts.open(&tmp).map_err(|e| io_err(&tmp, e))?;
    f.write_all(bytes).map_err(|e| io_err(&tmp, e))?;
    f.sync_all().map_err(|e| io_err(&tmp, e))?;
    drop(f);
    fs::rename(&tmp, path).map_err(|e| io_err(path, e))?;
    if let Some(dir) = path.parent() {
        #[cfg(unix)]
        fs::File::open(dir)
            .and_then(|d| d.sync_all())
            .map_err(|e| io_err(dir, e))?;
        #[cfg(not(unix))]
        let _ = dir;
    }
    Ok(())
}

fn create_dir(dir: &Path) -> Result<(), TlsError> {
    fs::create_dir_all(dir).map_err(|e| io_err(dir, e))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(dir, fs::Permissions::from_mode(0o700)).map_err(|e| io_err(dir, e))?;
    }
    Ok(())
}

fn read_opt(path: &Path) -> Result<Option<Vec<u8>>, TlsError> {
    match fs::read(path) {
        Ok(b) => Ok(Some(b)),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(io_err(path, e)),
    }
}

// ------------------------------------------------------------------------------------
// CertifiedKeyPair
// ------------------------------------------------------------------------------------

/// A certificate chain (leaf first) and its private key. `Debug` never shows the key.
pub struct CertifiedKeyPair {
    chain: Vec<CertificateDer<'static>>,
    key: PrivateKeyDer<'static>,
}

impl Clone for CertifiedKeyPair {
    fn clone(&self) -> Self {
        Self {
            chain: self.chain.clone(),
            key: self.key.clone_key(),
        }
    }
}

impl fmt::Debug for CertifiedKeyPair {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("CertifiedKeyPair")
            .field("chain_len", &self.chain.len())
            .field("fingerprint", &self.fingerprint())
            .field("key", &"[redacted]")
            .finish()
    }
}

impl CertifiedKeyPair {
    /// `chain` must be non-empty, leaf first.
    pub fn new(
        chain: Vec<CertificateDer<'static>>,
        key: PrivateKeyDer<'static>,
    ) -> Result<Self, TlsError> {
        if chain.is_empty() {
            return Err(cert_err("empty certificate chain"));
        }
        Ok(Self { chain, key })
    }

    /// Parse a PEM chain and a PEM private key (`files` mode, persisted certs). `what`
    /// names the source in errors.
    pub fn from_pem(cert_pem: &[u8], key_pem: &[u8], what: &str) -> Result<Self, TlsError> {
        let chain = CertificateDer::pem_slice_iter(cert_pem)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| cert_err(format!("{what}: bad certificate PEM: {e}")))?;
        if chain.is_empty() {
            return Err(cert_err(format!("{what}: no certificate in PEM")));
        }
        let key = PrivateKeyDer::from_pem_slice(key_pem)
            .map_err(|_| cert_err(format!("{what}: no usable private key in PEM")))?;
        Self::new(chain, key)
    }

    /// The leaf certificate.
    pub fn leaf_der(&self) -> &CertificateDer<'static> {
        &self.chain[0]
    }

    /// The chain, leaf first.
    pub fn chain(&self) -> &[CertificateDer<'static>] {
        &self.chain
    }

    /// A copy of the private key (DER).
    pub fn key_der(&self) -> PrivateKeyDer<'static> {
        self.key.clone_key()
    }

    /// The chain as concatenated PEM (leaf first).
    pub fn chain_pem(&self) -> String {
        self.chain
            .iter()
            .map(|c| pem_encode("CERTIFICATE", c))
            .collect()
    }

    /// The private key as PEM (tonic `Identity::from_pem`). Never log it.
    pub fn key_pem(&self) -> String {
        let label = match &self.key {
            PrivateKeyDer::Pkcs1(_) => "RSA PRIVATE KEY",
            PrivateKeyDer::Sec1(_) => "EC PRIVATE KEY",
            _ => "PRIVATE KEY",
        };
        pem_encode(label, self.key.secret_der())
    }

    /// `sha256:<hex>` of the leaf DER.
    pub fn fingerprint(&self) -> String {
        sha256_fingerprint(self.leaf_der())
    }

    /// The rustls form (key parsed by [`ostro_api::tls_provider`]; leaf/key match checked).
    pub fn to_rustls(&self) -> Result<Arc<rustls::sign::CertifiedKey>, TlsError> {
        rustls::sign::CertifiedKey::from_der(
            self.chain.clone(),
            self.key.clone_key(),
            &ostro_api::tls_provider(),
        )
        .map(Arc::new)
        .map_err(|e| cert_err(format!("certificate / key unusable: {e}")))
    }
}

// ------------------------------------------------------------------------------------
// SANs
// ------------------------------------------------------------------------------------

/// A subject alternative name.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum San {
    Dns(String),
    Ip(IpAddr),
    Uri(String),
}

impl San {
    /// Parse a host / `host:port` / `[v6]:port` / IP string into a DNS or IP SAN.
    pub fn from_host(s: &str) -> Option<San> {
        let s = s.trim();
        if s.is_empty() {
            return None;
        }
        if let Ok(sa) = s.parse::<std::net::SocketAddr>() {
            return Some(San::Ip(sa.ip()));
        }
        let t = s.trim_start_matches('[').trim_end_matches(']');
        if let Ok(ip) = t.parse::<IpAddr>() {
            return Some(San::Ip(ip));
        }
        let host = match s.rsplit_once(':') {
            Some((h, port)) if !port.is_empty() && port.bytes().all(|b| b.is_ascii_digit()) => h,
            _ => s,
        };
        let host = host.trim_end_matches('.').to_ascii_lowercase();
        let ok = !host.is_empty()
            && host.len() <= 253
            && host
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'-' | b'*'));
        ok.then_some(San::Dns(host))
    }

    fn to_rcgen(&self) -> Result<SanType, TlsError> {
        Ok(match self {
            San::Dns(d) => SanType::DnsName(
                d.as_str()
                    .try_into()
                    .map_err(|_| cert_err(format!("invalid DNS SAN {d:?}")))?,
            ),
            San::Ip(ip) => SanType::IpAddress(*ip),
            San::Uri(u) => SanType::URI(
                u.as_str()
                    .try_into()
                    .map_err(|_| cert_err(format!("invalid URI SAN {u:?}")))?,
            ),
        })
    }
}

/// The SANs of a parsed certificate (unparseable entries are skipped).
fn sans_of(cert: &X509Certificate<'_>) -> Result<BTreeSet<San>, TlsError> {
    let mut out = BTreeSet::new();
    let ext = cert
        .subject_alternative_name()
        .map_err(|e| cert_err(format!("bad subjectAltName: {e}")))?;
    if let Some(ext) = ext {
        for n in &ext.value.general_names {
            match n {
                GeneralName::DNSName(d) => {
                    out.insert(San::Dns(d.to_ascii_lowercase()));
                }
                GeneralName::URI(u) => {
                    out.insert(San::Uri((*u).to_owned()));
                }
                GeneralName::IPAddress(b) => {
                    let ip = match b.len() {
                        4 => <[u8; 4]>::try_from(*b).ok().map(IpAddr::from),
                        16 => <[u8; 16]>::try_from(*b).ok().map(IpAddr::from),
                        _ => None,
                    };
                    if let Some(ip) = ip {
                        out.insert(San::Ip(ip));
                    }
                }
                _ => {}
            }
        }
    }
    Ok(out)
}

/// The single `ostro://` URI SAN of a certificate.
fn identity_uri(cert: &X509Certificate<'_>) -> Result<String, TlsError> {
    let uris: Vec<String> = sans_of(cert)?
        .into_iter()
        .filter_map(|s| match s {
            San::Uri(u) if u.starts_with(IDENTITY_SCHEME) => Some(u),
            _ => None,
        })
        .collect();
    match uris.as_slice() {
        [one] => Ok(one.clone()),
        [] => Err(cert_err("certificate has no ostro:// identity SAN")),
        _ => Err(cert_err(
            "certificate has more than one ostro:// identity SAN",
        )),
    }
}

fn parse_cert(der: &[u8]) -> Result<X509Certificate<'_>, TlsError> {
    X509Certificate::from_der(der)
        .map(|(_, c)| c)
        .map_err(|e| cert_err(format!("unparseable certificate: {e}")))
}

// ------------------------------------------------------------------------------------
// Identities
// ------------------------------------------------------------------------------------

/// The identity carried by a node certificate (`ostro://<cluster_id>/node/<node_id>`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NodeIdentity {
    pub cluster_id: String,
    pub node_id: u64,
    /// `notAfter`, Unix seconds.
    pub not_after: i64,
}

impl NodeIdentity {
    /// The node identity URI.
    pub fn uri(cluster_id: &str, node_id: u64) -> String {
        format!("{IDENTITY_SCHEME}{cluster_id}/node/{node_id}")
    }

    /// Parse a node certificate. Worker certificates are rejected.
    pub fn from_der(cert_der: &[u8]) -> Result<NodeIdentity, TlsError> {
        let cert = parse_cert(cert_der)?;
        let uri = identity_uri(&cert)?;
        let rest = &uri[IDENTITY_SCHEME.len()..];
        let parts: Vec<&str> = rest.split('/').collect();
        match parts.as_slice() {
            [cluster, "node", id] if valid_id(cluster, 128) => {
                let node_id = id
                    .parse::<u64>()
                    .map_err(|_| cert_err("node identity SAN has a non-numeric node id"))?;
                Ok(NodeIdentity {
                    cluster_id: (*cluster).to_owned(),
                    node_id,
                    not_after: cert.validity().not_after.timestamp(),
                })
            }
            _ => Err(cert_err("not a node identity certificate")),
        }
    }
}

/// The identity carried by a worker client certificate
/// (`ostro://<cluster_id>/worker/<token_id>/<worker_id>`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct WorkerIdentity {
    pub cluster_id: String,
    pub token_id: String,
    pub worker_id: String,
    /// `notAfter`, Unix seconds.
    pub not_after: i64,
}

impl WorkerIdentity {
    /// The worker identity URI.
    pub fn uri(cluster_id: &str, token_id: &str, worker_id: &str) -> String {
        format!("{IDENTITY_SCHEME}{cluster_id}/worker/{token_id}/{worker_id}")
    }

    /// Parse a worker certificate. Node certificates are rejected.
    pub fn from_der(cert_der: &[u8]) -> Result<WorkerIdentity, TlsError> {
        let cert = parse_cert(cert_der)?;
        let uri = identity_uri(&cert)?;
        let rest = &uri[IDENTITY_SCHEME.len()..];
        let parts: Vec<&str> = rest.split('/').collect();
        match parts.as_slice() {
            [cluster, "worker", token, worker]
                if valid_id(cluster, 128)
                    && valid_id(token, MAX_ID_LEN)
                    && valid_id(worker, MAX_ID_LEN) =>
            {
                Ok(WorkerIdentity {
                    cluster_id: (*cluster).to_owned(),
                    token_id: (*token).to_owned(),
                    worker_id: (*worker).to_owned(),
                    not_after: cert.validity().not_after.timestamp(),
                })
            }
            _ => Err(cert_err("not a worker identity certificate")),
        }
    }
}

// ------------------------------------------------------------------------------------
// ClusterCa
// ------------------------------------------------------------------------------------

/// The cluster CA: one per `cluster_id`, shared by every node of the cluster (Phase 12
/// F13). `Debug` never shows the key.
pub struct ClusterCa {
    cluster_id: String,
    dir: PathBuf,
    cert_der: CertificateDer<'static>,
    issuer: Issuer<'static, KeyPair>,
}

impl fmt::Debug for ClusterCa {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("ClusterCa")
            .field("cluster_id", &self.cluster_id)
            .field("dir", &self.dir)
            .field("hash", &self.ca_hash())
            .field("key", &"[redacted]")
            .finish()
    }
}

/// CN of the CA of `cluster_id`.
fn ca_cn(cluster_id: &str) -> String {
    format!("ostro cluster {cluster_id}")
}

impl ClusterCa {
    pub const CERT_FILE: &'static str = "ca.crt";
    pub const KEY_FILE: &'static str = "ca.key";

    /// Load `<dir>/ca.{crt,key}`, or create them on first start. A CA of another cluster,
    /// a half-present pair, a corrupt file or a cert/key mismatch is an error naming the
    /// file; nothing is ever silently regenerated.
    pub fn load_or_create(dir: &Path, cluster_id: &str) -> Result<Self, TlsError> {
        check_cluster_id(cluster_id)?;
        create_dir(dir)?;
        let crt_path = dir.join(Self::CERT_FILE);
        let key_path = dir.join(Self::KEY_FILE);
        match (read_opt(&crt_path)?, read_opt(&key_path)?) {
            (Some(crt), Some(key)) => {
                Self::from_pem_bytes(dir, cluster_id, &crt, &key, &crt_path, &key_path)
            }
            (None, None) => {
                let ca = Self::generate(dir, cluster_id)?;
                ca.persist(&ca.key_pem())?;
                Ok(ca)
            }
            (Some(_), None) => Err(cert_err(format!(
                "{} exists but {} is missing; restore it or remove both to create a new CA",
                crt_path.display(),
                key_path.display()
            ))),
            (None, Some(_)) => Err(cert_err(format!(
                "{} exists but {} is missing; restore it or remove both to create a new CA",
                key_path.display(),
                crt_path.display()
            ))),
        }
    }

    /// Install a CA shared from another node of the cluster (Phase 12 distributes it):
    /// validates the pair and its cluster id, then replaces `<dir>/ca.{crt,key}`. Node and
    /// dev certificates of a previous CA are re-issued on the next load (they no longer
    /// verify against the new CA).
    pub fn import_pem(
        dir: &Path,
        cluster_id: &str,
        ca_crt_pem: &str,
        ca_key_pem: &str,
    ) -> Result<Self, TlsError> {
        check_cluster_id(cluster_id)?;
        create_dir(dir)?;
        let crt_path = dir.join(Self::CERT_FILE);
        let key_path = dir.join(Self::KEY_FILE);
        let ca = Self::from_pem_bytes(
            dir,
            cluster_id,
            ca_crt_pem.as_bytes(),
            ca_key_pem.as_bytes(),
            Path::new("<imported ca.crt>"),
            Path::new("<imported ca.key>"),
        )?;
        write_atomic(&key_path, ca_key_pem.as_bytes(), 0o600)?;
        write_atomic(&crt_path, ca_crt_pem.as_bytes(), 0o644)?;
        Ok(ca)
    }

    fn generate(dir: &Path, cluster_id: &str) -> Result<Self, TlsError> {
        let mut p = CertificateParams::default();
        let mut dn = DistinguishedName::new();
        dn.push(DnType::CommonName, ca_cn(cluster_id));
        p.distinguished_name = dn;
        p.is_ca = IsCa::Ca(BasicConstraints::Constrained(0));
        p.key_usages = vec![
            KeyUsagePurpose::KeyCertSign,
            KeyUsagePurpose::CrlSign,
            KeyUsagePurpose::DigitalSignature,
        ];
        p.serial_number = Some(random_serial()?);
        set_validity(&mut p, CA_LIFETIME)?;
        let key = KeyPair::generate_for(&PKCS_ECDSA_P256_SHA256)
            .map_err(|e| cert_err(format!("CA key generation: {e}")))?;
        let cert = p
            .self_signed(&key)
            .map_err(|e| cert_err(format!("CA self-signing: {e}")))?;
        Ok(Self {
            cluster_id: cluster_id.to_owned(),
            dir: dir.to_path_buf(),
            cert_der: cert.der().clone(),
            issuer: Issuer::new(p, key),
        })
    }

    fn persist(&self, key_pem: &str) -> Result<(), TlsError> {
        write_atomic(&self.dir.join(Self::KEY_FILE), key_pem.as_bytes(), 0o600)?;
        write_atomic(
            &self.dir.join(Self::CERT_FILE),
            self.cert_pem().as_bytes(),
            0o644,
        )
    }

    fn from_pem_bytes(
        dir: &Path,
        cluster_id: &str,
        crt: &[u8],
        key: &[u8],
        crt_path: &Path,
        key_path: &Path,
    ) -> Result<Self, TlsError> {
        let cert_der = CertificateDer::from_pem_slice(crt).map_err(|_| {
            cert_err(format!(
                "{}: not a PEM certificate (corrupt CA file)",
                crt_path.display()
            ))
        })?;
        let key_str = std::str::from_utf8(key)
            .map_err(|_| cert_err(format!("{}: not a PEM private key", key_path.display())))?;
        let key_pair = KeyPair::from_pem(key_str).map_err(|_| {
            cert_err(format!(
                "{}: not a usable PEM private key (corrupt CA key file)",
                key_path.display()
            ))
        })?;
        {
            let cert = parse_cert(&cert_der)
                .map_err(|e| cert_err(format!("{}: {e}", crt_path.display())))?;
            if !cert.is_ca() {
                return Err(cert_err(format!(
                    "{}: not a CA certificate",
                    crt_path.display()
                )));
            }
            use rcgen::PublicKeyData as _;
            if cert.public_key().raw != key_pair.subject_public_key_info().as_slice() {
                return Err(cert_err(format!(
                    "{} and {} do not match (key belongs to another certificate)",
                    crt_path.display(),
                    key_path.display()
                )));
            }
            let cn = cert
                .subject()
                .iter_common_name()
                .next()
                .and_then(|a| a.as_str().ok())
                .unwrap_or_default()
                .to_owned();
            if cn != ca_cn(cluster_id) {
                return Err(cert_err(format!(
                    "{}: CA belongs to another cluster ({cn:?}, expected {:?})",
                    crt_path.display(),
                    ca_cn(cluster_id)
                )));
            }
        }
        let issuer = Issuer::from_ca_cert_der(&cert_der, key_pair)
            .map_err(|e| cert_err(format!("{}: {e}", crt_path.display())))?;
        Ok(Self {
            cluster_id: cluster_id.to_owned(),
            dir: dir.to_path_buf(),
            cert_der: cert_der.into_owned(),
            issuer,
        })
    }

    /// The cluster this CA belongs to.
    pub fn cluster_id(&self) -> &str {
        &self.cluster_id
    }

    /// The directory holding `ca.{crt,key}` (and `node.*`, `dev.*`).
    pub fn dir(&self) -> &Path {
        &self.dir
    }

    /// The CA certificate (DER).
    pub fn cert_der(&self) -> &CertificateDer<'static> {
        &self.cert_der
    }

    /// The CA certificate (PEM).
    pub fn cert_pem(&self) -> String {
        pem_encode("CERTIFICATE", &self.cert_der)
    }

    /// The CA key as PEM (for distribution to other nodes of the cluster, Phase 12).
    /// Never log it.
    pub fn key_pem(&self) -> String {
        self.issuer.key().serialize_pem()
    }

    /// `sha256:<hex of the CA DER>` (what `--ca-hash` pins).
    pub fn ca_hash(&self) -> String {
        sha256_fingerprint(&self.cert_der)
    }

    /// A rustls root store holding only this CA.
    pub fn root_store(&self) -> Result<rustls::RootCertStore, TlsError> {
        let mut roots = rustls::RootCertStore::empty();
        roots
            .add(self.cert_der.clone())
            .map_err(|e| cert_err(format!("CA certificate rejected by rustls: {e}")))?;
        Ok(roots)
    }

    /// Issue a leaf (fresh P-256 key) with `sans`, `ekus` and `lifetime`; chain = [leaf, CA].
    pub fn issue_leaf(
        &self,
        common_name: &str,
        sans: &[San],
        ekus: &[ExtendedKeyUsagePurpose],
        lifetime: Duration,
    ) -> Result<CertifiedKeyPair, TlsError> {
        let mut p = CertificateParams::default();
        let mut dn = DistinguishedName::new();
        dn.push(DnType::CommonName, common_name);
        p.distinguished_name = dn;
        p.subject_alt_names = sans.iter().map(San::to_rcgen).collect::<Result<_, _>>()?;
        p.is_ca = IsCa::ExplicitNoCa;
        p.key_usages = vec![KeyUsagePurpose::DigitalSignature];
        p.extended_key_usages = ekus.to_vec();
        p.use_authority_key_identifier_extension = true;
        p.serial_number = Some(random_serial()?);
        set_validity(&mut p, lifetime)?;
        let key = KeyPair::generate_for(&PKCS_ECDSA_P256_SHA256)
            .map_err(|e| cert_err(format!("key generation: {e}")))?;
        let cert = p
            .signed_by(&key, &self.issuer)
            .map_err(|e| cert_err(format!("certificate signing: {e}")))?;
        let key_der = PrivateKeyDer::try_from(key.serialize_der())
            .map_err(|e| cert_err(format!("key encoding: {e}")))?;
        CertifiedKeyPair::new(vec![cert.der().clone(), self.cert_der.clone()], key_der)
    }

    /// The SANs of the node certificate of `node_id`: exactly one identity URI, the
    /// `[cluster] advertise` names/IPs, `localhost`, `127.0.0.1`, `::1`.
    pub fn node_sans(&self, node_id: u64, advertise: &[String]) -> Vec<San> {
        let mut set: BTreeSet<San> = advertise.iter().filter_map(|a| San::from_host(a)).collect();
        set.insert(San::Dns("localhost".to_owned()));
        set.insert(San::Ip(IpAddr::from([127, 0, 0, 1])));
        set.insert(San::Ip(IpAddr::from(std::net::Ipv6Addr::LOCALHOST)));
        set.insert(San::Uri(NodeIdentity::uri(&self.cluster_id, node_id)));
        set.into_iter().collect()
    }

    /// Issue a node certificate (1 y, serverAuth + clientAuth) for `node_id`; `sans` are
    /// extra DNS/IP names (the identity URI and loopback names are always added).
    pub fn issue_node_cert(
        &self,
        node_id: u64,
        sans: &[String],
    ) -> Result<CertifiedKeyPair, TlsError> {
        self.issue_leaf(
            &format!("ostro node {node_id}"),
            &self.node_sans(node_id, sans),
            &[
                ExtendedKeyUsagePurpose::ServerAuth,
                ExtendedKeyUsagePurpose::ClientAuth,
            ],
            LEAF_LIFETIME,
        )
    }

    /// Load `<dir>/node.{crt,key}` if it was issued by this CA for exactly these SANs and
    /// is valid for more than 30 days; else issue and persist a new one.
    pub fn load_or_issue_node_cert(
        &self,
        node_id: u64,
        advertise: &[String],
    ) -> Result<CertifiedKeyPair, TlsError> {
        let want = self.node_sans(node_id, advertise);
        self.load_or_issue("node", &want, || self.issue_node_cert(node_id, advertise))
    }

    /// Reuse `<dir>/<stem>.{crt,key}` when issued by this CA with exactly `want` SANs and
    /// valid for > [`REISSUE_WITHIN`]; else `issue()` and persist (key 0600).
    pub(crate) fn load_or_issue(
        &self,
        stem: &str,
        want: &[San],
        issue: impl FnOnce() -> Result<CertifiedKeyPair, TlsError>,
    ) -> Result<CertifiedKeyPair, TlsError> {
        let crt_path = self.dir.join(format!("{stem}.crt"));
        let key_path = self.dir.join(format!("{stem}.key"));
        if let (Some(crt), Some(key)) = (read_opt(&crt_path)?, read_opt(&key_path)?) {
            match self.reusable(&crt, &key, want, stem) {
                Ok(Some(pair)) => return Ok(pair),
                Ok(None) => {}
                Err(e) => {
                    tracing::warn!(file = %crt_path.display(), error = %e, "re-issuing unusable certificate");
                }
            }
        }
        let pair = issue()?;
        write_atomic(&key_path, pair.key_pem().as_bytes(), 0o600)?;
        write_atomic(&crt_path, pair.chain_pem().as_bytes(), 0o644)?;
        Ok(pair)
    }

    fn reusable(
        &self,
        crt: &[u8],
        key: &[u8],
        want: &[San],
        stem: &str,
    ) -> Result<Option<CertifiedKeyPair>, TlsError> {
        let pair = CertifiedKeyPair::from_pem(crt, key, stem)?;
        pair.to_rustls()?; // key matches the leaf
        let leaf = parse_cert(pair.leaf_der())?;
        let ca = parse_cert(&self.cert_der)?;
        if leaf.verify_signature(Some(ca.public_key())).is_err() {
            return Ok(None);
        }
        let reissue_at = unix_now()
            .saturating_add(i64::try_from(REISSUE_WITHIN.as_secs()).unwrap_or(i64::MAX / 4));
        if leaf.validity().not_after.timestamp() <= reissue_at {
            return Ok(None);
        }
        let have = sans_of(&leaf)?;
        let want: BTreeSet<San> = want.iter().cloned().collect();
        if have != want {
            return Ok(None);
        }
        // Always serve [leaf, CA] (the CA in the chain is what workers pin).
        CertifiedKeyPair::new(
            vec![pair.leaf_der().clone(), self.cert_der.clone()],
            pair.key_der(),
        )
        .map(Some)
    }

    /// Sign a worker CSR into a client certificate: SAN URI
    /// `ostro://<cluster>/worker/<token_id>/<worker_id>` only (the CSR's subject and SANs
    /// are ignored), EKU clientAuth, not a CA, `not_before = now - 60 s`,
    /// `not_after = now + ttl`. The CSR signature must verify and its key must be ECDSA
    /// P-256 or Ed25519. Returns the certificate DER.
    pub fn sign_worker_csr(
        &self,
        csr_der: &[u8],
        token_id: &str,
        worker_id: &str,
        ttl: Duration,
    ) -> Result<Vec<u8>, TlsError> {
        if !valid_id(token_id, MAX_ID_LEN) {
            return Err(cert_err(
                "token id must be 1-64 characters of [A-Za-z0-9._-]",
            ));
        }
        if !valid_id(worker_id, MAX_ID_LEN) {
            return Err(cert_err(
                "worker id must be 1-64 characters of [A-Za-z0-9._-]",
            ));
        }
        // Key type: ECDSA P-256 or Ed25519 only.
        {
            let (_, req) = X509CertificationRequest::from_der(csr_der)
                .map_err(|_| cert_err("unparseable CSR"))?;
            let spki = &req.certification_request_info.subject_pki;
            let alg = &spki.algorithm.algorithm;
            let ok = if *alg == OID_KEY_TYPE_EC_PUBLIC_KEY {
                spki.algorithm
                    .parameters
                    .as_ref()
                    .and_then(|p| p.as_oid().ok())
                    .is_some_and(|c| c == OID_EC_P256)
            } else {
                *alg == OID_SIG_ED25519
            };
            if !ok {
                return Err(cert_err("CSR key must be ECDSA P-256 or Ed25519"));
            }
        }
        let csr =
            CertificateSigningRequestParams::from_der(&CertificateSigningRequestDer::from(csr_der))
                .map_err(|e| match e {
                    rcgen::Error::InvalidCertificationRequestSignature => {
                        cert_err("CSR signature does not verify")
                    }
                    other => cert_err(format!("unusable CSR: {other}")),
                })?;
        let mut p = CertificateParams::default();
        let mut dn = DistinguishedName::new();
        dn.push(DnType::CommonName, format!("ostro worker {worker_id}"));
        p.distinguished_name = dn;
        p.subject_alt_names =
            vec![San::Uri(WorkerIdentity::uri(&self.cluster_id, token_id, worker_id)).to_rcgen()?];
        p.is_ca = IsCa::ExplicitNoCa;
        p.key_usages = vec![KeyUsagePurpose::DigitalSignature];
        p.extended_key_usages = vec![ExtendedKeyUsagePurpose::ClientAuth];
        p.use_authority_key_identifier_extension = true;
        p.serial_number = Some(random_serial()?);
        set_validity(&mut p, ttl)?;
        let cert = p
            .signed_by(&csr.public_key, &self.issuer)
            .map_err(|e| cert_err(format!("worker certificate signing: {e}")))?;
        Ok(cert.der().to_vec())
    }
}

fn check_cluster_id(cluster_id: &str) -> Result<(), TlsError> {
    if valid_id(cluster_id, 128) {
        Ok(())
    } else {
        Err(TlsError::Config(format!(
            "cluster id {cluster_id:?} cannot name a CA (want 1-128 characters of [A-Za-z0-9._-])"
        )))
    }
}
